import { pageAbsoluteUrl } from "@/lib/site";

/** Raster OG assets under `public/og/` (generated by `npm run generate:og`). */
export const DEFAULT_OG_IMAGE_PATH = "/og/yoobe-default.png";

const ROUTE_OG_BY_KEY: Record<string, string> = {
  home: "/og/yoobe-home.png",
  plataforma: "/og/yoobe-plataforma.png",
  "api-integracoes": "/og/yoobe-api.png",
  gamificacao: "/og/yoobe-gamificacao.png",
  "casos-de-uso": "/og/yoobe-casos.png",
  inteligencia: "/og/yoobe-inteligencia.png",
  "para-plataformas": "/og/yoobe-para-plataformas.png",
  educacao: "/og/yoobe-educacao.png",
  vendas: "/og/yoobe-vendas.png",
  comunidades: "/og/yoobe-comunidades.png",
  eventos: "/og/yoobe-eventos.png",
  "gamificacao-para-rh": "/og/yoobe-gamificacao.png",
  pricing: "/og/yoobe-pricing.png",
  seguranca: "/og/yoobe-seguranca.png",
};

export function resolveRouteOgImagePath(routeKey?: string): string {
  if (routeKey && ROUTE_OG_BY_KEY[routeKey]) {
    return ROUTE_OG_BY_KEY[routeKey];
  }
  return DEFAULT_OG_IMAGE_PATH;
}

export function resolveRouteOgImageUrl(routeKey?: string): string {
  return pageAbsoluteUrl(resolveRouteOgImagePath(routeKey));
}
